// Simple application with security best practices
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, param, validationResult } = require('express-validator');

const app = express();

// Security middleware
app.use(helmet());

// Trust proxy settings
app.set('trust proxy', 1);

// Rate limiting to prevent brute force and DoS attacks
const generalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: { error: 'Too many requests from this IP, please try again later.' },
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(generalLimiter);

// Stricter rate limiting for sensitive endpoints
const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5,
  message: { error: 'Too many attempts, please try again later.' },
});

// Body parsing middleware with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Custom validation error handler
const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      error: 'Validation failed',
      details: errors.array().map(err => ({
        field: err.path,
        message: err.msg
      }))
    });
  }
  next();
};

// Global error handler
const errorHandler = (err, req, res, next) => {
  console.error('Error:', {
    message: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
    path: req.path,
    method: req.method,
    ip: req.ip
  });

  // Don't leak error details in production
  const message = process.env.NODE_ENV === 'production' 
    ? 'Internal server error' 
    : err.message;

  res.status(err.status || 500).json({
    error: message
  });
};

// Health check endpoint
app.get('/health', generalLimiter, (req, res) => {
  res.json({ 
    status: 'ok',
    uptime: process.uptime(),
    timestamp: new Date().toISOString()
  });
});

// Get all users
app.get('/users', generalLimiter, (req, res, next) => {
  try {
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];
    res.json(users);
  } catch (err) {
    next(err);
  }
});

// Get user by ID with validation
app.get(
  '/users/:id',
  generalLimiter,
  param('id')
    .isInt({ min: 1, max: 999999 })
    .withMessage('User ID must be a positive integer')
    .toInt(),
  handleValidationErrors,
  (req, res, next) => {
    try {
      const { id } = req.params;
      // Simulate database lookup
      if (id > 100) {
        return res.status(404).json({ error: 'User not found' });
      }
      const user = { id, name: 'User ' + id, email: `user${id}@example.com` };
      res.json(user);
    } catch (err) {
      next(err);
    }
  }
);

// Create user with validation
app.post(
  '/users',
  strictLimiter,
  [
    body('name')
      .trim()
      .isLength({ min: 2, max: 100 })
      .withMessage('Name must be between 2 and 100 characters')
      .matches(/^[a-zA-Z0-9_\s-]+$/)
      .withMessage('Name contains invalid characters'),
    body('email')
      .isEmail()
      .normalizeEmail()
      .withMessage('Valid email is required')
      .isLength({ max: 254 })
      .withMessage('Email exceeds maximum length')
  ],
  handleValidationErrors,
  (req, res, next) => {
    try {
      const { name, email } = req.body;
      // Simulate user creation
      const newUser = {
        id: Math.floor(Math.random() * 1000) + 1,
        name,
        email
      };
      res.status(201).json(newUser);
    } catch (err) {
      next(err);
    }
  }
);

// 404 handler
app.use((req, res) => {
  res.status(404).json({ error: 'Resource not found' });
});

// Global error handler - MUST be last
app.use(errorHandler);

// Graceful shutdown handling
const server = app.listen(3000, () => {
  console.log('Server running on port 3000');
});

// Handle graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully');
  server.close(() => {
    console.log('Process terminated');
  });
});

process.on('SIGINT', () => {
  console.log('SIGINT received, shutting down gracefully');
  server.close(() => {
    console.log('Process terminated');
  });
});

// Handle uncaught exceptions
process.on('uncaughtException', (err) => {
  console.error('Uncaught Exception:', err);
  process.exit(1);
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  process.exit(1);
});

module.exports = { app, server };

