// Secure application with best practices for error handling and input validation
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const { body, param, validationResult } = require('express-validator');
const winston = require('winston');

const app = express();

// ============================================
// 1. SECURITY MIDDLEWARE
// ============================================

// Helmet for security headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", "data:", "https:"],
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  }
}));

// CORS configuration
const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  credentials: true,
  maxAge: 86400 // 24 hours
};
app.use(cors(corsOptions));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: process.env.RATE_LIMIT || 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// Stricter rate limiting for sensitive endpoints
const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5,
  message: 'Too many requests, please try again later',
});

// Body parsing with limits
app.use(express.json({ limit: '10kb' })); // Limit body size
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// ============================================
// 2. LOGGING SETUP
// ============================================

const logger = winston.createLogger({
  level: process.env.LOG_LEVEL || 'info',
  format: winston.format.combine(
    winston.format.timestamp(),
    winston.format.json()
  ),
  defaultMeta: { service: 'user-service' },
  transports: [
    new winston.transports.File({ filename: 'logs/error.log', level: 'error' }),
    new winston.transports.File({ filename: 'logs/combined.log' }),
  ],
});

if (process.env.NODE_ENV !== 'production') {
  logger.add(new winston.transports.Console({
    format: winston.format.simple(),
  }));
}

// Request logging middleware
app.use((req, res, next) => {
  logger.info({
    method: req.method,
    url: req.url,
    ip: req.ip,
    userAgent: req.get('user-agent'),
  });
  next();
});

// ============================================
// 3. VALIDATION MIDDLEWARES
// ============================================

// Validation error handler
const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    logger.warn('Validation failed', { errors: errors.array(), ip: req.ip });
    return res.status(400).json({
      success: false,
      message: 'Validation failed',
      errors: errors.array().map(err => ({
        field: err.path,
        message: err.msg
      }))
    });
  }
  next();
};

// Sanitize function to prevent XSS
const sanitizeInput = (input) => {
  if (typeof input !== 'string') return input;
  return input
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#x27;')
    .replace(/\//g, '&#x2F;');
};

// ============================================
// 4. ERROR HANDLING
// ============================================

// Custom error class
class AppError extends Error {
  constructor(message, statusCode, isOperational = true) {
    super(message);
    this.statusCode = statusCode;
    this.isOperational = isOperational;
    this.status = `${statusCode}`.startsWith('4') ? 'fail' : 'error';

    Error.captureStackTrace(this, this.constructor);
  }
}

// Async error wrapper - eliminates need for try-catch in routes
const catchAsync = (fn) => {
  return (req, res, next) => {
    Promise.resolve(fn(req, res, next)).catch(next);
  };
};

// ============================================
// 5. ROUTES WITH SECURITY IMPROVEMENTS
// ============================================

// Health check endpoint with validation
app.get('/health',
  [
    param('none').optional(), // No params expected
    handleValidationErrors
  ],
  catchAsync(async (req, res) => {
    // Validate query parameters
    const allowedParams = ['format'];
    const queryParams = Object.keys(req.query);

    const invalidParams = queryParams.filter(p => !allowedParams.includes(p));
    if (invalidParams.length > 0) {
      throw new AppError(`Invalid query parameters: ${invalidParams.join(', ')}`, 400);
    }

    const healthData = {
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      version: process.env.npm_package_version || '1.0.0',
      environment: process.env.NODE_ENV || 'development'
    };

    // Optional format parameter validation
    if (req.query.format && !['json', 'text'].includes(req.query.format)) {
      throw new AppError('Format must be "json" or "text"', 400);
    }

    logger.info('Health check requested', { ip: req.ip });

    if (req.query.format === 'text') {
      res.type('text/plain');
      return res.send(`Status: ${healthData.status}\nTimestamp: ${healthData.timestamp}`);
    }

    res.json({
      success: true,
      data: healthData
    });
  })
);

// Users endpoint with pagination and validation
app.get('/users',
  limiter,
  [
    param('none').optional(),
    handleValidationErrors
  ],
  catchAsync(async (req, res) => {
    // Validate and sanitize query parameters
    const page = Math.max(1, parseInt(req.query.page, 10) || 1);
    const limit = Math.min(100, Math.max(1, parseInt(req.query.limit, 10) || 10));

    // Whitelist allowed filters
    const allowedFilters = ['name', 'email'];
    const filters = {};

    allowedFilters.forEach(field => {
      if (req.query[field]) {
        // Sanitize input to prevent XSS
        filters[field] = sanitizeInput(req.query[field].trim());
      }
    });

    // Simulated database query with pagination
    const allUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
      { id: 3, name: 'Charlie', email: 'charlie@example.com' },
      { id: 4, name: 'Diana', email: 'diana@example.com' },
    ];

    // Apply filters
    let filteredUsers = allUsers;
    if (filters.name) {
      filteredUsers = filteredUsers.filter(u => 
        u.name.toLowerCase().includes(filters.name.toLowerCase())
      );
    }
    if (filters.email) {
      filteredUsers = filteredUsers.filter(u => 
        u.email.toLowerCase().includes(filters.email.toLowerCase())
      );
    }

    // Pagination
    const startIndex = (page - 1) * limit;
    const endIndex = page * limit;
    const paginatedUsers = filteredUsers.slice(startIndex, endIndex);

    logger.info('Users fetched', { 
      ip: req.ip, 
      page, 
      limit, 
      filters,
      totalResults: filteredUsers.length 
    });

    res.json({
      success: true,
      data: paginatedUsers,
      pagination: {
        currentPage: page,
        itemsPerPage: limit,
        totalItems: filteredUsers.length,
        totalPages: Math.ceil(filteredUsers.length / limit),
        hasNextPage: endIndex < filteredUsers.length,
        hasPrevPage: startIndex > 0
      }
    });
  })
);

// Get single user by ID with strict validation
app.get('/users/:id',
  strictLimiter,
  [
    param('id')
      .isInt({ min: 1 })
      .withMessage('ID must be a positive integer')
      .toInt(),
    handleValidationErrors
  ],
  catchAsync(async (req, res, next) => {
    const { id } = req.params;

    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    const user = users.find(u => u.id === id);

    if (!user) {
      throw new AppError('User not found', 404);
    }

    logger.info('User fetched', { userId: id, ip: req.ip });

    res.json({
      success: true,
      data: user
    });
  })
);

// Create user endpoint with comprehensive validation
app.post('/users',
  strictLimiter,
  [
    body('name')
      .trim()
      .notEmpty()
      .withMessage('Name is required')
      .isLength({ min: 2, max: 50 })
      .withMessage('Name must be between 2 and 50 characters')
      .matches(/^[a-zA-Z\s'-]+$/)
      .withMessage('Name can only contain letters, spaces, hyphens, and apostrophes')
      .customSanitizer(sanitizeInput),
    body('email')
      .trim()
      .notEmpty()
      .withMessage('Email is required')
      .isEmail()
      .withMessage('Must be a valid email address')
      .normalizeEmail()
      .isLength({ max: 255 })
      .withMessage('Email must not exceed 255 characters'),
    handleValidationErrors
  ],
  catchAsync(async (req, res) => {
    const { name, email } = req.body;

    // Check for duplicate email
    const existingUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    if (existingUsers.some(u => u.email === email)) {
      throw new AppError('Email already registered', 409);
    }

    const newUser = {
      id: existingUsers.length + 1,
      name: sanitizeInput(name),
      email: email.toLowerCase()
    };

    logger.info('User created', { userId: newUser.id, email, ip: req.ip });

    res.status(201).json({
      success: true,
      message: 'User created successfully',
      data: newUser
    });
  })
);

// ============================================
// 6. ERROR HANDLING MIDDLEWARE
// ============================================

// 404 handler
app.all('*', (req, res, next) => {
  next(new AppError(`Can't find ${req.originalUrl} on this server`, 404));
});

// Global error handler
app.use((err, req, res, next) => {
  // Set defaults
  err.statusCode = err.statusCode || 500;
  err.status = err.status || 'error';

  // Log error
  logger.error({
    message: err.message,
    stack: err.stack,
    statusCode: err.statusCode,
    ip: req.ip,
    url: req.originalUrl,
    method: req.method,
    isOperational: err.isOperational
  });

  // Don't leak error details in production
  if (process.env.NODE_ENV === 'production' && !err.isOperational) {
    return res.status(500).json({
      success: false,
      message: 'Something went wrong!'
    });
  }

  // Send error response
  res.status(err.statusCode).json({
    success: false,
    message: err.message,
    ...(process.env.NODE_ENV === 'development' && { stack: err.stack })
  });
});

// ============================================
// 7. SERVER STARTUP
// ============================================

// Graceful shutdown handling
const server = app.listen(process.env.PORT || 3000, () => {
  logger.info(`Server running on port ${process.env.PORT || 3000}`);
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (err) => {
  logger.error('UNHANDLED REJECTION! Shutting down...', err);
  server.close(() => {
    process.exit(1);
  });
});

// Handle uncaught exceptions
process.on('uncaughtException', (err) => {
  logger.error('UNCAUGHT EXCEPTION! Shutting down...', err);
  process.exit(1);
});

// Graceful termination
process.on('SIGTERM', () => {
  logger.info('SIGTERM received. Shutting down gracefully...');
  server.close(() => {
    logger.info('Process terminated');
  });
});

module.exports = app;

