// credential-scanner.js - Identifies potential secrets without using them
const fs = require('fs');
const path = require('path');

const SENSITIVE_PATTERNS = [
  { name: 'Database URL', pattern: /DATABASE_URL\s*=\s*(.+)/i },
  { name: 'AWS Access Key', pattern: /AWS_ACCESS_KEY_ID\s*=\s*(AKIA[0-9A-Z]{16})/i },
  { name: 'AWS Secret', pattern: /AWS_SECRET_ACCESS_KEY\s*=\s*(.{40})/i },
