// Secure application with improved error handling and input validation
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const winston = require('winston');
const Joi = require('joi');

const app = express();

// Configure security logger
const securityLogger = winston.createLogger({
  level: 'info',
  format: winston.format.combine(
    winston.format.timestamp(),
    winston.format.json()
  ),
  transports: [
    new winston.transports.File({ filename: 'security.log' }),
    new winston.transports.Console({ silent: process.env.NODE_ENV === 'production' })
  ]
});

// Apply Helmet for security headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", "data:", "https:"]
    }
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  }
}));

// Rate limiting middleware
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later',
  standardHeaders: true,
  legacyHeaders: false,
  handler: (req, res) => {
    securityLogger.warn(`Rate limit exceeded for IP: ${req.ip}`, {
      ip: req.ip,
      path: req.path,
      userAgent: req.get('user-agent')
    });
    res.status(429).json({ error: 'Too many requests, please try again later' });
  }
});

// Stricter rate limit for sensitive endpoints
const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5,
  message: 'Too many attempts, please try again later',
  handler: (req, res) => {
    securityLogger.warn(`Strict rate limit exceeded for IP: ${req.ip}`, {
      ip: req.ip,
      path: req.path
    });
    res.status(429).json({ error: 'Too many attempts, please try again later' });
  }
});

app.use(limiter);
app.use(express.json({ limit: '10kb' })); // Limit body size
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Input validation schemas using Joi
const schemas = {
  userId: Joi.object({
    id: Joi.number().integer().positive().required()
  }),

  queryParams: Joi.object({
    page: Joi.number().integer().min(1).max(100).default(1),
    limit: Joi.number().integer().min(1).max(100).default(10)
  }),

  userCreate: Joi.object({
    name: Joi.string().trim().min(1).max(100).pattern(/^[a-zA-Z0-9_\s-]+$/).required(),
    email: Joi.string().email().max(255).required()
  })
};

// Validation middleware factory
const validate = (schema, source = 'body') => {
  return (req, res, next) => {
    const dataToValidate = source === 'body' ? req.body : 
                           source === 'query' ? req.query : req.params;

    const { error, value } = schema.validate(dataToValidate, {
      abortEarly: false,
      stripUnknown: true
    });

    if (error) {
      const errorMessage = error.details.map(detail => detail.message).join(', ');
      securityLogger.warn('Validation failed', {
        ip: req.ip,
        path: req.path,
        errors: errorMessage
      });
      return res.status(400).json({ 
        error: 'Validation failed', 
        details: error.details.map(d => d.message)
      });
    }

    // Replace with validated/sanitized data
    if (source === 'body') req.body = value;
    else if (source === 'query') req.query = value;
    else req.params = value;

    next();
  };
};

// Sanitize user data before sending response
const sanitizeUser = (user) => {
  return {
    id: user.id,
    name: user.name,
    email: user.email
  };
};

// Health check endpoint
app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  } catch (error) {
    next(error);
  }
});

// Get all users with pagination
app.get('/users', validate(schemas.queryParams, 'query'), (req, res, next) => {
  try {
    // Mock data - in production, this would query a database
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' }
    ].map(sanitizeUser);

    const { page, limit } = req.query;
    const startIndex = (page - 1) * limit;
    const endIndex = startIndex + limit;
    const paginatedUsers = users.slice(startIndex, endIndex);

    res.json({
      data: paginatedUsers,
      pagination: {
        page,
        limit,
        total: users.length,
        totalPages: Math.ceil(users.length / limit)
      }
    });
  } catch (error) {
    next(error);
  }
});

// Get user by ID
app.get('/users/:id', validate(schemas.userId, 'params'), (req, res, next) => {
  try {
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' }
    ];

    const user = users.find(u => u.id === req.params.id);

    if (!user) {
      return res.status(404).json({ error: 'User not found' });
    }

    res.json({ data: sanitizeUser(user) });
  } catch (error) {
    next(error);
  }
});

// Create user endpoint (example with POST)
app.post('/users', strictLimiter, validate(schemas.userCreate, 'body'), (req, res, next) => {
  try {
    const { name, email } = req.body;

    // In production, check for duplicate email in database

    const newUser = {
      id: Date.now(), // Temporary ID generation
      name,
      email
    };

    securityLogger.info('New user created', { 
      userId: newUser.id,
      email: email 
    });

    res.status(201).json({ 
      message: 'User created successfully',
      data: sanitizeUser(newUser)
    });
  } catch (error) {
    next(error);
  }
});

// 404 handler for undefined routes
app.use((req, res) => {
  securityLogger.warn('404 - Route not found', {
    ip: req.ip,
    method: req.method,
    path: req.path,
    userAgent: req.get('user-agent')
  });
  res.status(404).json({ error: 'Resource not found' });
});

// Global error handling middleware
app.use((err, req, res, next) => {
  // Log error details
  securityLogger.error('Unhandled error', {
    error: err.message,
    stack: err.stack,
    ip: req.ip,
    path: req.path,
    method: req.method
  });

  // Don't leak error details in production
  const isProduction = process.env.NODE_ENV === 'production';

  res.status(err.status || 500).json({
    error: err.status ? err.message : 'Internal server error',
    ...(isProduction ? {} : { stack: err.stack })
  });
});

// Graceful shutdown handling
process.on('SIGTERM', () => {
  securityLogger.info('SIGTERM received, shutting down gracefully');
  process.exit(0);
});

process.on('SIGINT', () => {
  securityLogger.info('SIGINT received, shutting down gracefully');
  process.exit(0);
});

// Handle uncaught exceptions
process.on('uncaughtException', (err) => {
  securityLogger.error('Uncaught Exception', { error: err.message, stack: err.stack });
  process.exit(1);
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  securityLogger.error('Unhandled Rejection', { reason, stack: reason?.stack });
});

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  securityLogger.info(`Server started on port ${PORT}`, {
    port: PORT,
    env: process.env.NODE_ENV || 'development'
  });
});

module.exports = { app, server };

