// INPUT VALIDATION UTILITIES
// ============================================

/**
 * Validates and sanitizes a string input
 * @param {string} input - The input to validate
 * @param {Object} options - Validation options
 * @returns {Object} - { isValid: boolean, value: string, error: string }
 */
const validateString = (input, options = {}) => {
  const { minLength = 1, maxLength = 255, pattern = null, required = true } = options;

  if (required && (input === undefined || input === null || input === '')) {
    return { isValid: false, error: 'Field is required' };
  }

  if (!required && (input === undefined || input === null || input === '')) {
    return { isValid: true, value: '' };
  }

  const str = String(input).trim();

  if (str.length < minLength) {
    return { isValid: false, error: `Minimum length is ${minLength}` };
  }

  if (str.length > maxLength) {
    return { isValid: false, error: `Maximum length is ${maxLength}` };
  }

  if (pattern && !pattern.test(str)) {
    return { isValid: false, error: 'Invalid format' };
  }

  // Basic XSS prevention - remove potentially dangerous characters
  const sanitized = str
    .replace(/[<>]/g, '')
    .replace(/javascript:/gi, '')
    .replace(/on\w+=/gi, '');

  return { isValid: true, value: sanitized };
};

/**
 * Validates an email address
 * @param {string} email - The email to validate
 * @returns {Object} - { isValid: boolean, value: string, error: string }
 */
const validateEmail = (email) => {
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  const result = validateString(email, { 
    pattern: emailRegex, 
    maxLength: 254,
    required: true 
  });

  if (!result.isValid) {
    return result;
  }

  return { isValid: true, value: result.value.toLowerCase() };
};

/**
 * Validates a numeric ID
 * @param {any} id - The ID to validate
 * @returns {Object} - { isValid: boolean, value: number, error: string }
 */
const validateId = (id) => {
  const numId = Number(id);

  if (isNaN(numId) || !Number.isInteger(numId)) {
    return { isValid: false, error: 'ID must be a valid integer' };
  }

  if (numId <= 0) {
    return { isValid: false, error: 'ID must be positive' };
  }

  if (numId > Number.MAX_SAFE_INTEGER) {
    return { isValid: false, error: 'ID is too large' };
  }

  return { isValid: true, value: numId };
};

